INSERT INTO `v1_0a531e2f6a471c03022ba867595beb1ab9c0239d1c95e37f554aabcbce9d07c7` VALUES (73, "ティア", 1, 2, 0, 2, 0, -363, "あんたにとって\nプリンセスって誰なの？", 0, 140301, 1);
INSERT INTO `v1_0a531e2f6a471c03022ba867595beb1ab9c0239d1c95e37f554aabcbce9d07c7` VALUES (73, "ティア", 2, 3, 1, 5, 1.384, -363, "ちょっ……なによ\nセクハラすんじゃないわよ\nほら、早く選びなさいよ", 0, 140301, 2);
INSERT INTO `v1_0a531e2f6a471c03022ba867595beb1ab9c0239d1c95e37f554aabcbce9d07c7` VALUES (73, "ティア", 3, 5, 1, 5, 0, -363, "……～っ……\nや、やめなさいっての\nくすぐったいんだから……", 0, 140301, 3);
INSERT INTO `v1_0a531e2f6a471c03022ba867595beb1ab9c0239d1c95e37f554aabcbce9d07c7` VALUES (73, "ティア", 4, 5, 1, 3, 6.175, -363, "……あんた。\nあたしをからかってるの？\nそ、それとも……", 0, 140301, 4);
INSERT INTO `v1_0a531e2f6a471c03022ba867595beb1ab9c0239d1c95e37f554aabcbce9d07c7` VALUES (73, "ティア", 5, 4, 1, 4, 0, -363, "あたしを選ぼう、とか……\n言わないわよね……？", 0, 140301, 5);
